// WF-RA-01 RA_Validate_Module_Batch — canonical envelope validation.
const CANONICAL_ERROR_CODES = new Set(['INVALID_AGGREGATION_INPUT','CONTEXT_MISMATCH','MISSING_REQUIRED_FIELDS','MISSING_MODULE_RESULTS','DUPLICATE_STEP_IDS']);
const PERMITTED_RESULT_STATUSES = new Set(['success','partial','failed','no_action']);
function canonicalError(code, message, missingFields, details){
  if(!CANONICAL_ERROR_CODES.has(code)) code='INVALID_AGGREGATION_INPUT';
  return { status_kind:'error', result_type:'aggregation_error', error:{ code, message, missing_fields: missingFields||[], details: details||{} } };
}
function validate(payload){
  const requiredTop=['status_kind','result_type','execution_context_id','thread_id','tenant_id','aggregation_input'];
  const missingTop=requiredTop.filter(f=>!(f in payload));
  if(missingTop.length) return [false, canonicalError('INVALID_AGGREGATION_INPUT','Aggregation envelope missing required top-level fields.', missingTop)];
  if(payload.status_kind!=='success'||payload.result_type!=='module_batch')
    return [false, canonicalError('INVALID_AGGREGATION_INPUT','Aggregation envelope must be a canonical success/module_batch payload.', [], {status_kind:payload.status_kind, result_type:payload.result_type})];
  const ai=payload.aggregation_input;
  const missingAi=['aggregation_allowed','response_generation_allowed','module_execution_completed','domain_writes_performed','module_results','expected_step_ids'].filter(f=>!(f in ai));
  if(missingAi.length) return [false, canonicalError('INVALID_AGGREGATION_INPUT','Aggregation input is incomplete.', missingAi)];
  if(!ai.aggregation_allowed) return [false, canonicalError('INVALID_AGGREGATION_INPUT','Aggregation is not allowed by upstream guard flags.')];
  if(ai.response_generation_allowed) return [false, canonicalError('INVALID_AGGREGATION_INPUT','Response generation must remain disabled in aggregation stage.')];
  if(!ai.module_execution_completed) return [false, canonicalError('INVALID_AGGREGATION_INPUT','Module execution must be completed before aggregation.')];
  if(ai.domain_writes_performed) return [false, canonicalError('INVALID_AGGREGATION_INPUT','Aggregation stage must start from a no-write batch envelope.')];
  const mr=ai.module_results, esi=ai.expected_step_ids;
  if(!Array.isArray(mr)||mr.length===0) return [false, canonicalError('MISSING_MODULE_RESULTS','Aggregation requires a non-empty module_results list.')];
  if(!Array.isArray(esi)||esi.length===0) return [false, canonicalError('MISSING_REQUIRED_FIELDS','Aggregation requires expected_step_ids.', ['expected_step_ids'])];
  const required=['module_name','step_id','result_type','status','summary','actions_executed','artifacts','observations','proposals','confidence','needs_followup','followup_requests'];
  const seen=new Set(); const normalized=[];
  for(let i=0;i<mr.length;i++){
    const r=mr[i];
    const miss=required.filter(f=>!(f in r));
    if(miss.length) return [false, canonicalError('MISSING_REQUIRED_FIELDS','Module result at index '+i+' is incomplete.', miss)];
    if(!PERMITTED_RESULT_STATUSES.has(r.status)) return [false, canonicalError('INVALID_AGGREGATION_INPUT','Invalid module result status at index '+i+'.', [], {status:r.status})];
    if(seen.has(r.step_id)) return [false, canonicalError('DUPLICATE_STEP_IDS','Duplicate step_id detected in module batch.', [], {step_id:r.step_id})];
    seen.add(r.step_id); normalized.push(JSON.parse(JSON.stringify(r)));
  }
  const missingSteps=esi.filter(s=>!seen.has(s));
  if(missingSteps.length) return [false, canonicalError('MISSING_MODULE_RESULTS','Expected step results are missing from the module batch.', missingSteps)];
  return [true, { execution_context_id: payload.execution_context_id, thread_id: payload.thread_id, tenant_id: payload.tenant_id, expected_step_ids: esi.slice(), module_results: normalized, idempotency_key: payload.idempotency_key || ('aggregate:'+payload.execution_context_id) }];
}
const out=[];
for(const it of items){
  const payload = (it.json && Object.keys(it.json).length) ? it.json : {};
  const [ok, result] = validate(payload);
  if(ok){ out.push({ json: { _valid:true, _envelope: result, _original_input: payload } }); }
  else { out.push({ json: { _valid:false, _error: result, _original_input: payload } }); }
}
return out;

// WF-RA-01 RA_Verify_Context_Match — verify DB row matches envelope tenant/thread
const out = [];
for (let i = 0; i < items.length; i++) {
  const row = items[i].json || {};
  let envelope = null;
  try { envelope = $('RA_Validate_Module_Batch').first().json._envelope; } catch (e) { envelope = null; }
  if (!envelope) {
    out.push({ json: { _context_ready: false, _error: { status_kind:'error', result_type:'aggregation_error', error:{ code:'CONTEXT_MISMATCH', message:'Envelope missing at verify step.', missing_fields: [], details: {} } } } });
    continue;
  }
  const hasRow = row && row.id;
  if (!hasRow) {
    out.push({ json: { _context_ready: false, _envelope: envelope, _error: { status_kind:'error', result_type:'aggregation_error', error:{ code:'CONTEXT_MISMATCH', message:'execution_context row not found.', missing_fields: [], details: { execution_context_id: envelope.execution_context_id, tenant_id: envelope.tenant_id } } } } });
    continue;
  }
  const rowTid = String(row.tenant_id||'').toLowerCase();
  const envTid = String(envelope.tenant_id||'').toLowerCase();
  const rowThr = String(row.thread_id||'').toLowerCase();
  const envThr = String(envelope.thread_id||'').toLowerCase();
  if (rowTid !== envTid || rowThr !== envThr) {
    out.push({ json: { _context_ready: false, _envelope: envelope, _error: { status_kind:'error', result_type:'aggregation_error', error:{ code:'CONTEXT_MISMATCH', message:'tenant_id/thread_id mismatch between envelope and execution_contexts row.', missing_fields: [], details: { row_tenant_id: row.tenant_id, env_tenant_id: envelope.tenant_id, row_thread_id: row.thread_id, env_thread_id: envelope.thread_id } } } } });
    continue;
  }
  out.push({ json: { _context_ready: true, _envelope: envelope, _context_row: row } });
}
return out;

// WF-RA-01 RA_Aggregate_Module_Results — canonical aggregation.
function rollup(statuses){
  if(statuses.every(s=>s==='success')) return 'success';
  if(statuses.every(s=>s==='failed')) return 'failed';
  if(statuses.every(s=>s==='no_action')) return 'no_action';
  return 'partial';
}
const out = [];
for(const it of items){
  const env = it.json._envelope;
  const ctx = it.json._context_row || {};
  const results = env.module_results;
  const statuses = results.map(r=>r.status);
  const status = rollup(statuses);
  const actions_executed=[], artifacts=[], observations=[], proposals=[], followup_requests=[], module_names=[];
  const per_status_counts = { success:0, partial:0, failed:0, no_action:0 };
  let total_confidence=0;
  for(const r of results){
    module_names.push(r.module_name);
    per_status_counts[r.status] = (per_status_counts[r.status]||0)+1;
    total_confidence += Number(r.confidence||0);
    actions_executed.push(...JSON.parse(JSON.stringify(r.actions_executed||[])));
    artifacts.push(...JSON.parse(JSON.stringify(r.artifacts||[])));
    observations.push(...(r.observations||[]));
    proposals.push(...JSON.parse(JSON.stringify(r.proposals||[])));
    if(r.needs_followup) followup_requests.push(...JSON.parse(JSON.stringify(r.followup_requests||[])));
  }
  const avg_confidence = Math.round((total_confidence/results.length)*10000)/10000;
  const aggregated_result = {
    status,
    summary: 'Aggregated '+results.length+' module result(s) with rollup status '+status+'.',
    module_results_count: results.length,
    module_names,
    per_status_counts,
    actions_executed,
    artifacts,
    observations,
    proposals,
    confidence: avg_confidence,
    needs_followup: followup_requests.length>0,
    followup_requests,
    expected_step_ids: env.expected_step_ids.slice(),
    returned_step_ids: results.map(r=>r.step_id)
  };
  out.push({ json: { _envelope: env, _context_row: ctx, _aggregated_result: aggregated_result } });
}
return out;

// WF-RA-01 RA_Build_Downstream_Envelope — build canonical success envelope for WF-SU-01.
const out = [];
for(const it of items){
  const env = it.json._envelope;
  const aggregated = it.json._aggregated_result;
  out.push({ json: {
    status_kind: 'success',
    result_type: 'aggregated_result',
    execution_context_id: env.execution_context_id,
    thread_id: env.thread_id,
    tenant_id: env.tenant_id,
    aggregated_result: aggregated,
    state_update_allowed: true,
    response_generation_allowed: false,
    domain_writes_performed: false,
    allowed_next_stage: 'WF-SU-01',
    idempotency_key: env.idempotency_key
  } });
}
return out;

// WF-RA-01 RA_Return_Error — invalid input envelope.
const out=[];
for(const it of items){
  const err = it.json._error || { status_kind:'error', result_type:'aggregation_error', error:{ code:'INVALID_AGGREGATION_INPUT', message:'Unknown invalid input.', missing_fields:[], details:{} } };
  out.push({ json: err });
}
return out;

// WF-RA-01 RA_Return_Context_Error — context mismatch / aggregation error.
const out=[];
for(const it of items){
  const err = it.json._error || { status_kind:'error', result_type:'aggregation_error', error:{ code:'CONTEXT_MISMATCH', message:'Unknown context mismatch.', missing_fields:[], details:{} } };
